{
  "gateway": "apple_ads_native_action",
  "mode": "direct",
  "description": "Run any Apple Ads Platform API v1 or legacy Campaign Management API v5 endpoint through one native dispatcher. v1 uses action names beginning apple_ads_v1_; v5 retires 2027-01-26. Supports dry-runs, destructive confirmation, result projection, and bounded pagination.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Apple Ads native action/tool name, e.g. FIND_CAMPAIGNS, apple_ads_find_campaigns, or apple_ads_campaign_ads_list."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional Apple Ads connection ID."
      },
      "org_id": {
        "type": [
          "string",
          "number"
        ],
        "description": "Apple Ads v5 orgId for X-AP-Context. For Platform API v1 prefer account_id/adAccountId."
      },
      "account_id": {
        "type": [
          "string",
          "number"
        ],
        "description": "Apple Ads Platform API v1 adAccountId for X-AP-Context; accepted as the stored-context selector."
      },
      "ad_account_id": {
        "type": [
          "string",
          "number"
        ],
        "description": "Explicit alias for the Apple Ads Platform API v1 adAccountId context."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Templated path params. Friendly fields such as campaign_id/ad_group_id are also accepted."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "description": "Native Apple Ads params. For find endpoints, Selector fields are accepted here and sent as the top-level body."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query params for GET/DELETE endpoints."
      },
      "payload": {
        "anyOf": [
          {
            "$ref": "#/properties/path_params"
          },
          {
            "type": "array",
            "items": {}
          }
        ],
        "description": "Native Apple Ads request body (object) or bulk array. Find selectors are top-level; reporting wraps selector; keyword bulk accepts arrays."
      },
      "aggregate_pages": {
        "type": "boolean",
        "default": false,
        "description": "Fetch additional Selector/report pages by offset when true."
      },
      "max_pages": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 25,
        "description": "Page cap for aggregate_pages."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required for destructive live calls."
      },
      "dry_run": {
        "type": "boolean",
        "default": true,
        "description": "Writes preview by default; read actions ignore it."
      },
      "skip_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Bypass curated Apple Ads write preflight."
      },
      "override_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Alias for skip_preflight."
      },
      "idempotency_key": {
        "type": "string",
        "description": "Idempotency key for writes."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Project MCP result records to these fields."
      },
      "fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Alias for result_fields unless the action has a native fields parameter."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 2000,
        "description": "Cap returned arrays in the MCP result. Use repeated paged calls for larger exports."
      },
      "compact": {
        "type": "boolean",
        "default": false,
        "description": "Remove null, empty string, and empty object values from the MCP result."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
